    sandbox_ref01_data = (await sandbox_ref01_ent.create(sandbox_ref01_data)).data()
    assert(null != sandbox_ref01_data.id)


    // LIST
    const sandbox_ref01_match = {}
    sandbox_ref01_match['session_id'] = setup.idmap['session01']

    const sandbox_ref01_list = (await sandbox_ref01_ent.list(sandbox_ref01_match)).map((e) => e.data())

    assert(!isempty(select(sandbox_ref01_list, { id: sandbox_ref01_data.id })))


    // UPDATE
    const sandbox_ref01_data_up0 = {}
    sandbox_ref01_data_up0.id = sandbox_ref01_data.id

    const sandbox_ref01_markdef_up0 = { name: 'command', value: 'Mark01-sandbox_ref01_' + setup.now }
    sandbox_ref01_data_up0 [sandbox_ref01_markdef_up0.name] = sandbox_ref01_markdef_up0.value

    const sandbox_ref01_resdata_up0 = (await sandbox_ref01_ent.update(sandbox_ref01_data_up0)).data()
    assert(sandbox_ref01_resdata_up0.id === sandbox_ref01_data_up0.id)

    assert(sandbox_ref01_resdata_up0[sandbox_ref01_markdef_up0.name] === sandbox_ref01_markdef_up0.value)


    // LOAD
    const sandbox_ref01_match_dt0 = {}
    sandbox_ref01_match_dt0.id = sandbox_ref01_data.id
    const sandbox_ref01_data_dt0 = (await sandbox_ref01_ent.load(sandbox_ref01_match_dt0)).data()
    assert(sandbox_ref01_data_dt0.id === sandbox_ref01_data.id)


    // REMOVE
    const sandbox_ref01_match_rm0 = {}
    sandbox_ref01_match_rm0.id = sandbox_ref01_data.id
    await sandbox_ref01_ent.remove(sandbox_ref01_match_rm0)
  

    // LIST
    const sandbox_ref01_match_rt0 = {}
    sandbox_ref01_match_rt0['session_id'] = setup.idmap['session01']

    const sandbox_ref01_list_rt0 = (await sandbox_ref01_ent.list(sandbox_ref01_match_rt0)).map((e) => e.data())

    assert(isempty(select(sandbox_ref01_list_rt0, { id: sandbox_ref01_data.id })))


